SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',to_jsonb(r),'type',to_jsonb(pg_identify_object('pg_type'::regclass,r.rngtypid,0)),'subtype',to_jsonb(pg_identify_object('pg_type'::regclass,r.rngsubtype,0)),'multirange',to_jsonb(pg_identify_object('pg_type'::regclass,r.rngmultitypid,0))) ORDER BY r.rngtypid),'[]'::jsonb) AS payload FROM pg_range r JOIN pg_type t ON t.oid=r.rngtypid WHERE t.typnamespace='public'::regnamespace) AS capture